var paths=UnityEditor.AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Maps/Buildings","Assets/Environment/Stairwell"}).Select(UnityEditor.AssetDatabase.GUIDToAssetPath).Where(p=>p.Contains("Wall_")||p.Contains("Floor_3x3")||p.Contains("Stairwell_3m")||p.Contains("ThinConcreteStairs"));
return paths.Select(p=> {var g=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(p);return new {path=p,transforms=g.GetComponentsInChildren<UnityEngine.Transform>(true).Select(t=>new{name=t.name,pos=t.localPosition.ToString("F3"),scale=t.localScale.ToString("F3"),active=t.gameObject.activeSelf}).ToArray(),renderers=g.GetComponentsInChildren<UnityEngine.Renderer>(true).Select(r=>new{name=r.name,bounds=r.bounds.ToString()}).ToArray(),colliders=g.GetComponentsInChildren<UnityEngine.Collider>(true).Select(c=>new{name=c.name,type=c.GetType().Name}).ToArray()};}).ToArray();
